import sympy

def gen(a1, n_terms):
    seq = [a1]
    def ok(x, seq):
        for a in seq:
            if sympy.gcd(x, a) == 1:
                return False
        return True
    x = a1
    while len(seq) < n_terms:
        x += 1
        if ok(x, seq):
            seq.append(x)
    return seq

