from sympy import primefactors, gcd
from math import gcd as g

def seq(a1, N):
    terms=[a1]
    while len(terms)<N:
        x=terms[-1]+1
        while True:
            if all(g(x,t)>1 for t in terms):
                terms.append(x); break
            x+=1
    return terms

def check_SP(a1,N=200):
    terms=seq(a1,N)
    bad=[]
    for i in range(len(terms)):
        for j in range(i+1,len(terms)):
            gg=g(terms[i],terms[j])
            # common primes
            cps=primefactors(gg)
            if not any(p<=a1 for p in cps):
                bad.append((terms[i],terms[j],cps))
    return terms[:15], bad

